#!/bin/zsh
# 🏭️ The multiview repair of one plant of batch MV-3, the last step of its chain (after its generator and after the silhouette ops of `🧰️silhouette/*/ops/<id>.json`), idempotent: `rebind.ts` when column 4 of `plants.tsv` starts with `rebind` (its further words are flags of `rebind.ts`) (the elevation shapes on the bone of their front and plan twins), the asset's own `fix-<id>.ts` if there is one, `bodyview.ts` when `bodyview/<id>.json` exists (single parts of one view drawn from their body), `prism.ts` when `prism/<id>.json` exists (hanging parts as prisms of their height), `crown500.ts` when `crown500/<id>.json` exists (the 1:500 crown from the foliage masses of the 1:200 body), `clean.ts --ops` when `clean/<id>.json` exists (staircase outlines thinned), `strands.ts` when `strands/<id>.flags` exists (its flags; hanging curtains as lofts under the plan), then `carry.ts` (depth plates below the flat front and plan outlines of the parts the wind poses turn; its flags are column 2 of `plants.tsv`; `-` there leaves the step out for a plant whose views agree in every pose and that only has anchors to bind), then `body.ts --ops body/<id>.json` when that file exists (one real body per part in the place of its depth plates, absolute values), then `anchors.ts --ops ops/<id>.json` (the anchors on the drawing of their bone, absolute values). It writes the catalog file and prints the gate over every pose, clip instant and transition. Every step runs through the machine-wide memory queue (`q.sh`, 1000 MB). make.sh <id>
BATCH=MV-3 source "${0:A:h}/../MR/env.sh"
q() { if [[ -n "$MV3_GRANT" ]]; then local dir="$2" t="$3" r="$GEN/log/rss-$$.txt" code; shift 3; (cd "$dir" && /usr/bin/time -l -o "$r" timeout "$t" "$@"); code=$?; echo "$(( $(awk '/maximum resident set size/{print $1}' "$r") / 1048576 )) MB ${${@[2,5]}:t}" >> "$GEN/log/rss.txt"; rm -f "$r"; return $code; else "$W/q.sh" "$@"; fi }
a="$1"; cf=(${=$(awk -F'\t' -v a="$a" '$1==a{print $2}' "$W/plants.tsv")}); mkdir -p "$GEN/log"
rb=(${=$(awk -F'\t' -v a="$a" '$1==a{print $4}' "$W/plants.tsv")}); if [[ "$rb[1]" == rebind ]]; then q 1000 "$T" 900 "$B" "$W/rebind.ts" "$a" --write $rb[2,-1] | tail -1; fi
if [[ -f "$W/fix-$a.ts" ]]; then q 1000 "$T" 600 "$B" "$W/fix-$a.ts" --write | tail -1; fi
if [[ -f "$W/bodyview/$a.json" ]]; then q 1000 "$T" 1800 "$B" "$W/bodyview.ts" "$a" --work "$GEN/work" --write > "$GEN/log/$a-make-bodyview.log" 2>&1; echo "bodyview exit $? $(grep -v DEBUG "$GEN/log/$a-make-bodyview.log" | tail -1 | cut -c1-160)"; fi
if [[ -f "$W/prism/$a.json" ]]; then q 1000 "$T" 1800 "$B" "$W/prism.ts" "$a" --write > "$GEN/log/$a-make-prism.log" 2>&1; echo "prism exit $? $(grep -v DEBUG "$GEN/log/$a-make-prism.log" | tail -1 | cut -c1-200)"; fi
if [[ -f "$W/crown500/$a.json" ]]; then q 1000 "$T" 900 "$B" "$W/crown500.ts" "$a" --write > "$GEN/log/$a-make-crown500.log" 2>&1; echo "crown500 exit $? $(grep -v DEBUG "$GEN/log/$a-make-crown500.log" | tail -1 | cut -c1-160)"; fi
if [[ -f "$W/clean/$a.json" ]]; then q 1000 "$T" 1200 "$B" "$W/clean.ts" "$a" --ops "$W/clean/$a.json" --write > "$GEN/log/$a-make-clean.log" 2>&1; echo "clean exit $? $(grep -v DEBUG "$GEN/log/$a-make-clean.log" | tail -1 | cut -c1-200)"; fi
if [[ -f "$W/strands/$a.flags" ]]; then q 1000 "$T" 2400 "$B" "$W/strands.ts" "$a" --write ${=$(< "$W/strands/$a.flags")} > "$GEN/log/$a-make-strands.log" 2>&1; echo "strands exit $? $(grep -v DEBUG "$GEN/log/$a-make-strands.log" | tail -1 | cut -c1-200)"; fi
[[ "$cf[1]" == "-" ]] && echo "no carry" > "$GEN/log/$a-make-carry.log" || q 1000 "$T" 3000 "$B" "$W/carry.ts" "$a" --write $cf > "$GEN/log/$a-make-carry.log" 2>&1; echo "carry exit $? $(tail -2 "$GEN/log/$a-make-carry.log" | cut -c1-120 | tr '\n' ';')"
if [[ -f "$W/body/$a.json" ]]; then q 1000 "$T" 1200 "$B" "$W/body.ts" "$a" --ops "$W/body/$a.json" --write > "$GEN/log/$a-make-body.log" 2>&1; echo "body exit $? $(grep -v DEBUG "$GEN/log/$a-make-body.log" | tail -1 | cut -c1-200)"; fi
q 1000 "$T" 3000 "$B" "$W/anchors.ts" "$a" --ops "$W/ops/$a.json" --write > "$GEN/log/$a-make-anchors.log" 2>&1; echo "anchors exit $? $(tail -2 "$GEN/log/$a-make-anchors.log" | cut -c1-140 | tr '\n' ';')"
q 1000 "$T" 1800 "$B" "$M/gate.ts" "$a" > "$GEN/log/$a-make-gate.log" 2>&1; echo "gate exit $? $(tail -1 "$GEN/log/$a-make-gate.log")"
